function renderDayPlan(){const root=$("dashboardPlan");root.innerHTML="";const days=weekSessionsForGoal(),today=(new Date().getDay()+6)%7;days.slice(today).concat(days.slice(0,today)).slice(0,4).forEach(function(day,index){const isToday=index===0,row=document.createElement("div");row.className="plan-day"+(isToday?" today":"");row.innerHTML='<span class="day-initial">'+day.day.slice(0,1)+'</span><div><strong>'+escape(day.name)+'</strong><small>'+escape(day.meta)+'</small></div><span class="day-status">'+(isToday?"TODAY":/rest|recovery/i.test(day.name)?"RECOVER":"PLANNED")+'</span>';root.appendChild(row)})}
