function mealIdea(style){const ideas={Vegan:"Build a meal around lentils, beans, tofu or tempeh, whole grains and vegetables.",Vegetarian:"Try dairy, lentils, beans, tofu or paneer with grains and vegetables.",Pescatarian:"Mix fish, eggs, dairy, legumes, whole grains and vegetables.",Halal:"Choose halal protein options with grains, legumes, fruit and vegetables.",Jain:"Use foods that fit your practice, such as lentils, dairy, grains, nuts and selected vegetables."};return ideas[style]||"Pair a protein source with vegetables or fruit and a satisfying grain. Adjust to your preferences."}
function renderFoodResults(query){const root=$("foodResults");if(!root)return;root.innerHTML="";const q=(query||"").toLowerCase().trim();if(!q)return;const pref=state.profile.foodStyle||"Omnivore";foodCatalog.filter(function(x){return x.name.toLowerCase().includes(q)&&(pref==="Omnivore"||x.style.includes("All")||x.style.includes(pref))}).slice(0,5).forEach(function(food){const row=document.createElement("div");row.className="food-result";row.innerHTML="<div><strong>"+escape(food.name)+"</strong><small>"+food.cal+" kcal · P "+food.p+" g · C "+food.c+" g · F "+food.f+" g</small></div><button type=\"button\">＋ Add</button>";row.querySelector("button").addEventListener("click",function(){addFood(food.name,food.cal,food.p,food.c,food.f)});root.appendChild(row)});if(!root.children.length)root.innerHTML='<div class="empty-state">No matching sample food for this search and preference.</div>'}
