function renderInsights(){const sessions=state.sessions.slice().sort(function(a,b){return new Date(b.at)-new Date(a.at)});$("totalSessions").textContent=sessions.length;$("totalMinutes").textContent=sessions.reduce(function(sum,x){return sum+(x.minutes||0)},0);$("totalPRs").textContent=state.prs.length;$("activeDays").textContent=new Set(sessions.map(function(x){return todayKey(new Date(x.at))})).size;$("historyCount").textContent=sessions.length+" entries";$("analyticsTitle").textContent=historyRange==="all"?"Your full training history":"Your last "+historyRange+" days";
 const cutoff=new Date();cutoff.setHours(0,0,0,0);if(historyRange!=="all")cutoff.setDate(cutoff.getDate()-Number(historyRange)+1);const filtered=sessions.filter(function(s){return historyRange==="all"||new Date(s.at)>=cutoff}),chart=$("analyticsChart"),axis=$("chartAxis");chart.innerHTML="";axis.innerHTML="";
 let groups=[];if(historyRange==="7"){const base=weekStart();groups=Array.from({length:7},function(_,i){const d=new Date(base);d.setDate(d.getDate()+i);return{label:d.toLocaleDateString(undefined,{weekday:"short"}),date:todayKey(d),count:0}});filtered.forEach(function(s){const g=groups.find(function(x){return x.date===todayKey(new Date(s.at))});if(g)g.count++})}else if(historyRange==="30"){groups=Array.from({length:5},function(_,i){return{label:"W"+(i+1),count:0}});filtered.forEach(function(s){const age=Math.floor((Date.now()-new Date(s.at).getTime())/86400000);const index=Math.max(0,Math.min(4,4-Math.floor(age/7)));groups[index].count++})}else{const now=new Date();groups=Array.from({length:12},function(_,i){const d=new Date(now.getFullYear(),now.getMonth()-11+i,1);return{label:d.toLocaleDateString(undefined,{month:"short"}),year:d.getFullYear(),month:d.getMonth(),count:0}});filtered.forEach(function(s){const d=new Date(s.at),g=groups.find(function(x){return x.year===d.getFullYear()&&x.month===d.getMonth()});if(g)g.count++})}
 const max=Math.max(1,...groups.map(function(x){return x.count}));groups.forEach(function(g){const wrap=document.createElement("div");wrap.className="chart-bar-group";const bar=document.createElement("i");bar.className="chart-bar";bar.style.height=(g.count?Math.max(12,g.count/max*100):3)+"%";bar.dataset.value=g.count+" sessions";wrap.appendChild(bar);chart.appendChild(wrap);const label=document.createElement("span");label.textContent=g.label;axis.appendChild(label)});
 const list=$("workoutHistory");list.innerHTML="";if(!sessions.length)list.innerHTML='<div class="empty-state">Your completed sessions will build your all-time history here.</div>';sessions.slice(0,30).forEach(function(s){const row=document.createElement("div");row.className="history-item";row.innerHTML="<div><strong>"+escape(s.name)+"</strong><small>"+new Date(s.at).toLocaleString(undefined,{dateStyle:"medium",timeStyle:"short"})+" · "+(s.minutes||0)+" min</small></div><span>"+(s.exercises||0)+" movements</span>";list.appendChild(row)});
 const prs=$("prList");prs.innerHTML="";if(!state.prs.length)prs.innerHTML='<div class="empty-state">Log a personal record when you reach a milestone.</div>';state.prs.slice().sort(function(a,b){return new Date(b.at)-new Date(a.at)}).forEach(function(pr){const row=document.createElement("div");row.className="pr-item";row.innerHTML="<strong>"+escape(pr.exercise)+"</strong><span>"+escape(pr.value)+" "+escape(pr.unit)+"</span>";prs.appendChild(row)});
}
