function renderLeaderboard(){const scope=$("rankScope").value,country=$("rankCountry").value,region=$("rankRegion").value,type=$("rankType").value;const rows=leaderboardData.filter(function(x){return(scope==="world"||x.country===country)&&(scope!=="region"||region==="All"||x.city===region)&&(type==="All"||x.type===type)}).sort(function(a,b){return b.score-a.score});const root=$("leaderboard");root.innerHTML="";if(!rows.length){root.innerHTML='<div class="empty-state">No sample athletes match these filters.</div>';return}rows.slice(0,12).forEach(function(x,i){const row=document.createElement("div");row.className="rank-row";row.innerHTML='<span class="rank-number">'+String(i+1).padStart(2,"0")+'</span><div><strong>'+escape(x.name)+'</strong><small>'+escape(x.city)+", "+escape(x.country)+" · "+escape(x.type)+'</small></div><span class="rank-score">'+x.score+" sessions</span>";root.appendChild(row)})}
function renderBuddies(){const root=$("buddyMatches");root.innerHTML='<div class="empty-state">Set a few preferences and tap Find my matches.</div>'}
function findBuddies(event){event.preventDefault();const form=event.currentTarget,goal=form.elements.goal.value,time=form.elements.time.value,level=form.elements.level.value,city=form.elements.region.value.trim().toLowerCase();const rows=buddyData.map(function(x){let score=(x.goal===goal?3:0)+(x.time===time?2:0)+(x.level===level?2:0)+(city&&x.city.toLowerCase().includes(city)?3:0);return{person:x,score:score}}).sort(function(a,b){return b.score-a.score}).slice(0,3);const root=$("buddyMatches");root.innerHTML="";rows.forEach(function(entry){const x=entry.person,row=document.createElement("div");row.className="buddy-card";row.innerHTML='<span class="buddy-avatar">'+escape(x.avatar)+'</span><div><strong>'+escape(x.name)+' · '+escape(x.city)+'</strong><small>'+escape(x.style)+' · '+escape(x.level)+' · '+escape(x.time)+'</small></div><span class="buddy-score">'+Math.min(99,58+entry.score*7)+'%</span>';root.appendChild(row)});notify("Sample training partners found.")}
function filteredTrainers(){const specialty=$("trainerSpecialty").value,mode=$("trainerMode").value;return trainerData.filter(function(t){return(specialty==="all"||t.specialty===specialty)&&(mode==="all"||t.mode===mode)})}
function renderTrainers(){let list=filteredTrainers();if(!list.length)list=trainerData.slice(0,3);trainerIndex=(trainerIndex%list.length+list.length)%list.length;const root=$("trainerCards");root.innerHTML="";const cards=list.slice(trainerIndex).concat(list.slice(0,trainerIndex)).slice(0,3);cards.forEach(function(t){const saved=state.savedTrainers.includes(t.name),card=document.createElement("article");card.className="trainer-card";card.dataset.trainer=t.name;card.innerHTML='<div class="trainer-photo">'+escape(t.avatar)+'</div><h3>'+escape(t.name)+'</h3><p class="trainer-meta">'+escape(t.specialty)+' · '+escape(t.city)+' · '+escape(t.mode)+'</p><div class="trainer-rating">★ '+escape(t.rating)+' · '+t.reviews+' reviews · '+escape(t.price)+'</div><p class="trainer-meta">'+escape(t.bio)+'</p><div class="trainer-tags">'+t.tags.map(function(tag){return"<span>"+escape(tag)+"</span>"}).join("")+'</div><div class="trainer-actions"><button class="button pass-button" data-trainer-pass="'+escape(t.name)+'">Pass</button><button class="button like-button" data-trainer-save="'+escape(t.name)+'">'+(saved?"Saved ✓":"♡ Save")+'</button></div>';root.appendChild(card)})}
