function renderProfile(){const name=state.profile.name||"Alex Morgan",$name=name.split(" ")[0];$("sideName").textContent=name;$("topName").textContent=name;$("sideAvatar").textContent=$name[0].toUpperCase();$("topAvatar").textContent=$name[0].toUpperCase();$("sidePlan").textContent=state.profile.goal+" · "+state.profile.experience}
