function appendMessage(text,who){const row=document.createElement("div");row.className="message "+(who==="user"?"user-message":"coach-message");row.textContent=text;$("chatMessages").appendChild(row);$("chatMessages").scrollTop=$("chatMessages").scrollHeight;return row}
function demoCoachReply(q){const msg=q.toLowerCase();if(/injury|numb|tingl|deform|swelling/.test(msg))return"I can’t diagnose an injury. Stop movements that cause pain. If there is numbness, a visible deformity, cold/discoloured skin, severe worsening pain or you cannot bear weight, seek urgent medical care.";if(/sore|pain|recover/.test(msg))return"How intense is the soreness from 0–10, and where is it? This coach preview can help you record a check-in, but it cannot diagnose. Keep painful movements out and get qualified advice if symptoms worsen.";if(/food|meal|protein|diet/.test(msg))return"Use your Nutrition profile for a rough calorie and macro starting estimate, then log meals from the food list. For a medical diet or health condition, work with a qualified dietitian.";if(/plan|workout|train|routine/.test(msg))return"Tell me your goal, available days and equipment. You can also set a weekly movement target in Training; the suggested daily pace updates when you log reps.";if(/sleep|steps|activity/.test(msg))return"Log steps, sleep and active minutes in Health & recovery. Device syncing is not connected yet, so those values are entered manually.";return"I’m the FORGE coach preview. Ask me about training, food logging, recovery, or your weekly movement goal. Live AI turns on after the secure service is connected."}
async function sendChat(event){event.preventDefault();const form=event.currentTarget,question=form.elements.message.value.trim();if(!question)return;form.elements.message.value="";appendMessage(question,"user");const pending=appendMessage("Thinking through it…","coach");try{const result=await requestAI("coach",{message:question,profile:{goal:state.profile.goal,experience:state.profile.experience},history:state.sessions.slice(0,5).map(function(x){return{name:x.name,at:x.at,minutes:x.minutes}})});pending.remove();appendMessage(result&&result.text?result.text:demoCoachReply(question),"coach");if(!(result&&result.text))$("aiStatus").textContent="Demo coach · secure AI not connected"}catch(e){pending.remove();appendMessage(demoCoachReply(question),"coach");$("aiStatus").textContent="Demo coach · "+(e.message||"AI unavailable")}}
async function requestAI(task,payload){if(!supabaseClient||!currentUser)throw new Error("Sign in and configure the secure AI service to enable live AI.");const response=await supabaseClient.functions.invoke("forge-ai",{body:Object.assign({task:task},payload)});if(response.error)throw response.error;if(response.data&&response.data.error)throw new Error(response.data.error);return response.data}
function startWorkout(){const names=state.routine.length?state.routine.slice(0,8):recommendExerciseNames().slice(0,Math.max(3,Math.min(6,Number(state.profile.days)||4)));session={name:(state.profile.goal||"General")+" · coached session",items:names.map(function(n){return catalog.find(function(x){return x[0]===n})||[n,"Training","Full body","Your choice","Beginner","Move within a comfortable range."]}),index:0,sets:0,done:0,total:names.length,completed:[]};sessionStartedAt=Date.now();$("sessionTitle").textContent=session.name;$("setCount").textContent="0";$("sessionDialog").showModal();renderSession();sessionTimer=setInterval(function(){const sec=Math.floor((Date.now()-sessionStartedAt)/1000);$("sessionElapsed").textContent=String(Math.floor(sec/60)).padStart(2,"0")+":"+String(sec%60).padStart(2,"0")},1000)}
function renderSession(){if(!session)return;const item=session.items[session.index];$("sessionCounter").textContent="Exercise "+(session.index+1)+" of "+session.total;$("sessionExerciseName").textContent=item[0];$("sessionExerciseMeta").textContent="3 sets · "+(item[4]==="Beginner"?"8–12 reps":"6–10 reps")+" · "+item[3];$("sessionExerciseTip").textContent=item[5];$("sessionEmoji").textContent=symbolFor(item[1]);$("setCount").textContent=session.sets;$("sessionProgress").style.width=Math.round(session.done/session.total*100)+"%";$("[data-action=session-next]").textContent=session.sets>=3?"Next exercise →":"Complete set"}
function completeSet(){if(session.sets<3){session.sets++;$("setCount").textContent=session.sets;if(session.sets<3)startRestTimer()}else{session.completed.push(session.items[session.index][0]);session.done++;if(session.index<session.total-1){session.index++;session.sets=0;renderSession()}else finishWorkout()}}
function finishWorkout(){clearInterval(sessionTimer);sessionTimer=null;if(restInterval){clearInterval(restInterval);restInterval=null}const seconds=Math.max(1,Math.round((Date.now()-sessionStartedAt)/1000)),minutes=Math.max(1,Math.round(seconds/60));state.sessions.unshift({id:Date.now(),name:session.name,at:new Date().toISOString(),minutes:minutes,exercises:session.completed.length});persist();renderAll();$("sessionDialog").close();notify("Session saved to your history. Nice work.")}
function startRestTimer(){clearInterval(restInterval);let sec=60;function draw(){$("restClock").textContent=String(Math.floor(sec/60)).padStart(2,"0")+":"+String(sec%60).padStart(2,"0")}draw();restInterval=setInterval(function(){sec--;draw();if(sec<=0){clearInterval(restInterval);restInterval=null;notify("Rest complete. Ready when you are.")}},1000)}
function skipRest(){if(restInterval){clearInterval(restInterval);restInterval=null}$("restClock").textContent="01:00"}
function updateMovementGoal(event){event.preventDefault();const form=event.currentTarget,name=form.elements.movement.value.trim(),target=Number(form.elements.target.value);if(!name||target<1){notify("Enter a valid movement and weekly target.");return}state.movement.name=name;state.movement.target=target;persist();renderAll();notify("Your weekly target is saved.")}
function logReps(event){event.preventDefault();const input=event.currentTarget.elements.reps,amount=Number(input.value);if(!Number.isInteger(amount)||amount<1){notify("Enter a whole number of reps.");return}getMovementWeek().completed+=amount;state.movement.logs.unshift({amount:amount,at:new Date().toISOString()});persist();renderAll();input.value="";notify(amount.toLocaleString()+" "+state.movement.name.toLowerCase()+" logged. Your daily pace updated.")}
function addRoutine(name){if(!name)return;if(!state.routine.includes(name)){state.routine.push(name);persist();renderRoutine();notify("Added to your routine.")}else notify("Already in your routine.")}
function removeRoutine(index){state.routine.splice(index,1);persist();renderRoutine()}
async function analyzePlan(){const output=$("trainingInsight"),last=state.sessions[0],mv=getMovementWeek();output.textContent="Reviewing your recent sessions…";try{const result=await requestAI("analyze",{goal:state.profile.goal,weeklyTarget:mv,workouts:state.sessions.slice(0,20)});if(result&&result.text){output.textContent=result.text;notify("Your AI training review is ready.");return}}catch(e){}let advice;if(!last)advice="Start with two or three manageable sessions this week. The AI coach can personalize this after connection.";else if(mv.completed<mv.target)advice="Your goal has "+(mv.target-mv.completed).toLocaleString()+" "+mv.name.toLowerCase()+" remaining. About "+Math.ceil((mv.target-mv.completed)/(7-((new Date().getDay()+6)%7)))+" a day keeps it on pace.";else advice="You have reached your weekly movement goal. Keep a recovery day in the plan.";output.textContent="Local coaching preview: "+advice;renderInsight();notify("Local training review updated.")}
