function saveTrainingProfile(event){event.preventDefault();const f=event.currentTarget;state.profile=Object.assign(state.profile,{name:f.elements.name.value.trim()||"Athlete",goal:f.elements.goal.value,experience:f.elements.experience.value,days:Math.max(1,Math.min(7,Number(f.elements.days.value)||4))});persist();$("profileDialog").close();renderAll();notify("Your training plan is updated for "+state.profile.goal+".")}
function openNutritionDialog(){const f=$("nutritionForm"),p=state.profile;["age","sex","height","weight","activity","nutritionGoal","foodStyle","waterGoal"].forEach(function(k){if(p[k]!==undefined&&f.elements[k])f.elements[k].value=p[k]});$("nutritionDialog").showModal()}
function calculateDiet(event){event.preventDefault();const f=event.currentTarget,age=Number(f.elements.age.value),height=Number(f.elements.height.value),weight=Number(f.elements.weight.value),activity=Number(f.elements.activity.value),sex=f.elements.sex.value,goal=f.elements.nutritionGoal.value,waterGoal=Number(f.elements.waterGoal.value),foodStyle=f.elements.foodStyle.value;if(age<18){notify("This estimate is for adults 18 and over.");return}const bmr=10*weight+6.25*height-5*age+(sex==="male"?5:-161),maintenance=Math.round(bmr*activity),calories=Math.round(maintenance+(goal==="lose"?-200:goal==="gain"?200:0));if(calories<1200){notify("That estimate is unusually low; please speak with a dietitian before using it.");return}state.profile=Object.assign(state.profile,{age:age,height:height,weight:weight,sex:sex,activity:activity,nutritionGoal:goal,foodStyle:foodStyle,calorieGoal:calories,waterGoal:waterGoal,proteinGoal:Math.round(weight*1.4),carbsGoal:Math.round(calories*.45/4),fatGoal:Math.round(calories*.3/9)});persist();$("nutritionDialog").close();renderAll();notify("Your nutrition starting targets are ready.")}
function resetMeals(){if(!confirm("Clear today's food and water log?"))return;state.meals[todayKey()]=[];state.water[todayKey()]=0;persist();renderAll()}
function adjustWater(amount){state.water[todayKey()]=Math.max(0,(state.water[todayKey()]||0)+amount);persist();renderNutrition();renderDashboard()}
function removeMeal(index){currentMeals().splice(index,1);persist();renderNutrition();renderDashboard()}
function addPR(event){event.preventDefault();const f=event.currentTarget,name=f.elements.exercise.value.trim(),value=Number(f.elements.value.value),unit=f.elements.unit.value;if(!name||value<=0){notify("Enter an exercise and a positive result.");return}const old=state.prs.find(function(x){return x.exercise.toLowerCase()===name.toLowerCase()&&x.unit===unit});if(old&&(unit==="min"?value>=old.numeric:value<=old.numeric)){notify("That does not beat your saved record yet.");return}state.prs=state.prs.filter(function(x){return !(x.exercise.toLowerCase()===name.toLowerCase()&&x.unit===unit)});state.prs.unshift({exercise:name,value:value,numeric:value,unit:unit,at:new Date().toISOString()});persist();renderInsights();f.reset();notify("Personal record saved.")}
function saveHealth(event){event.preventDefault();const f=event.currentTarget,entry={steps:Number(f.elements.steps.value),sleep:Number(f.elements.sleep.value),active:Number(f.elements.active.value),energy:f.elements.energy.value,day:todayKey(),at:new Date().toISOString()};if(entry.sleep<0||entry.sleep>24||entry.steps<0||entry.active<0){notify("Check the health values and try again.");return}state.healthLogs.unshift(entry);state.healthLogs=state.healthLogs.slice(0,365);persist();renderHealth();renderDashboard();f.reset();notify("Today's check-in is saved.")}
function checkSymptoms(event){event.preventDefault();const f=event.currentTarget,flags=Array.from(f.querySelectorAll('[name="redFlag"]:checked')).map(function(x){return x.value}),pain=Number(f.elements.pain.value),area=f.elements.area.value,entry={area:area,pain:pain,flags:flags,at:new Date().toISOString()};state.symptoms.unshift(entry);state.symptoms=state.symptoms.slice(0,100);persist();let message="Saved your note. This is not a diagnosis and cannot rule out injury. Stop or change movements that hurt; seek qualified help if pain persists or worsens.",urgent=false;if(flags.some(function(x){return["numbness","deformity","circulation"].includes(x)})){message="Urgent warning: numbness/tingling, a visible deformity, or cold/discoloured skin after injury needs emergency medical assessment. Stop exercise and seek urgent care now.";urgent=true}else if(flags.includes("weight")||flags.includes("severe")||pain>=8){message="Urgent warning: severe or worsening pain/swelling or inability to bear weight can need urgent assessment. Stop exercise and seek urgent local medical care.";urgent=true}else if(pain>=5)message="High soreness reported. Skip painful training and seek a clinician if pain or swelling is increasing.";const node=$("symptomResult");node.textContent=area+" · "+pain+"/10. "+message;node.classList.toggle("urgent",urgent);notify("Symptom note saved. No diagnosis was made.")}
function createNutritionProfile(event){return calculateDiet(event)}
function renderLeaderboardFromPrefs(){state.communityPrefs={scope:$("rankScope").value,country:$("rankCountry").value,region:$("rankRegion").value,type:$("rankType").value};persist();renderLeaderboard()}
function saveTrainer(name){if(state.savedTrainers.includes(name))state.savedTrainers=state.savedTrainers.filter(function(x){return x!==name});else state.savedTrainers.push(name);persist();renderTrainers();notify(state.savedTrainers.includes(name)?"Coach saved.":"Coach removed from saves.")}
function connectTrainer(name){notify("Coach profile saved locally. Live trainer messaging is not connected yet.");}
function shareText(text){if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(text).then(function(){notify("Copied to clipboard.")}).catch(function(){notify(text)});else notify(text)}
function previewFoodPhoto(file){if(!file)return;if(!file.type.startsWith("image/")){notify("Choose an image file.");return}if(file.size>4*1024*1024){notify("For this demo, use an image under 4 MB.");return}const reader=new FileReader();reader.onload=function(){foodPhotoData=reader.result;const preview=$("foodPhotoPreview");preview.innerHTML="";const img=document.createElement("img");img.src=foodPhotoData;img.alt="Selected meal";preview.appendChild(img);const result=$("foodPhotoResult");result.hidden=false;result.innerHTML='<p><strong>Photo ready.</strong> When AI is configured, it will estimate likely foods and portions. Review all results before logging.</p><button class="button button-dark" data-action="analyze-food">Analyze photo with AI</button><span class="privacy-note">Nothing is uploaded until you press Analyze.</span>'};reader.readAsDataURL(file)}
async function analyzeFoodPhoto(){if(!foodPhotoData){notify("Choose a meal photo first.");return}const result=$("foodPhotoResult");result.innerHTML="<p>Analyzing the image…</p>";try{const data=await requestAI("food",{image:foodPhotoData});if(!data||!Array.isArray(data.items)||!data.items.length)throw new Error("No food estimates returned.");result.innerHTML="";const intro=document.createElement("p");intro.textContent="AI estimate · review before logging. Portions and nutrition may be inaccurate.";result.appendChild(intro);data.items.slice(0,6).forEach(function(x){const row=document.createElement("div");row.className="food-result";row.innerHTML="<div><strong>"+escape(x.name||"Food estimate")+"</strong><small>"+Number(x.calories||0)+" kcal · P "+Number(x.protein||0)+" g · C "+Number(x.carbs||0)+" g · F "+Number(x.fat||0)+" g</small></div><button type=\"button\">Add</button>";row.querySelector("button").addEventListener("click",function(){addFood(x.name||"AI food estimate",Number(x.calories||0),Number(x.protein||0),Number(x.carbs||0),Number(x.fat||0))});result.appendChild(row)});if(data.note){const note=document.createElement("p");note.className="microcopy";note.textContent=data.note;result.appendChild(note)}}catch(e){result.hidden=false;result.innerHTML="<p>Food AI is not connected yet. Your photo stays in this tab. Use food search to log a meal.</p><button class=\"button button-outline\" data-action=\"clear-food-photo\">Remove photo</button>";notify(e.message||"Food analysis unavailable.")}}
async function sendTrainerPrompt(name){openCoach("I’m interested in coaching with "+name+".")}
function enableTrainerSwipe(){const root=$("trainerCards");root.addEventListener("pointerdown",function(e){if(e.target.closest("button"))return;trainerStartX=e.clientX});root.addEventListener("pointerup",function(e){if(trainerStartX===null)return;const delta=e.clientX-trainerStartX;trainerStartX=null;if(Math.abs(delta)>55)stepTrainer(delta<0?1:-1)})}
function setFormData(form,data){Object.keys(data||{}).forEach(function(k){if(form.elements[k])form.elements[k].value=data[k]})}
function handleNavigation(event){const nav=event.target.closest("[data-nav]");if(nav){event.preventDefault();goToPage(nav.dataset.nav);return}const prompt=event.target.closest("[data-prompt]");if(prompt){openCoach(prompt.dataset.prompt);return}}
function actionClick(event){const el=event.target.closest("[data-action]");if(!el)return;const action=el.dataset.action;const handlers={
"open-settings":openNutritionDialog,"open-nutrition-profile":openNutritionDialog,"edit-profile":openTrainingProfile,"open-coach":function(){openCoach()},"close-coach":closeCoach,"start-workout":startWorkout,"analyze":analyzePlan,"water-plus":function(){adjustWater(250)},"water-minus":function(){adjustWater(-250)},"reset-meals":resetMeals,"trainer-prev":function(){stepTrainer(-1)},"trainer-next":function(){stepTrainer(1)},"signup":function(){signup()},"signout":function(){signOut()},"detail-add":function(){addRoutine(el.dataset.exerciseName);$("exerciseDialog").close()},"rest-start":startRestTimer,"rest-skip":skipRest,"set-minus":function(){if(session){session.sets=Math.max(0,session.sets-1);$("setCount").textContent=session.sets;renderSession()}},"set-plus":function(){completeSet()},"session-next":function(){completeSet()},"session-prev":function(){if(session&&session.index>0){session.index--;session.sets=0;renderSession()}},"refresh-meal-ideas":function(){const styles=["Build a meal around protein, produce and a grain.","Choose portions that leave you comfortably fueled for training.","Keep favourite foods in the plan; consistency beats perfection."];$("dietDescription").textContent=styles[Math.floor(Math.random()*styles.length)];},"share-invite":function(){shareText("Join my FORGE training circle!")}, "analyze-food":analyzeFoodPhoto,"clear-food-photo":function(){foodPhotoData=null;$("foodPhoto").value="";$("foodPhotoPreview").innerHTML="<span>＋</span><small>Your meal preview appears here</small>";$("foodPhotoResult").hidden=true}
};if(handlers[action])handlers[action]()}
function setupEvents(){
 document.addEventListener("click",function(event){handleNavigation(event);actionClick(event);const add=event.target.closest("[data-add-exercise]");if(add){addRoutine(add.dataset.addExercise);return}const remove=event.target.closest("[data-remove-routine]");if(remove){removeRoutine(Number(remove.dataset.removeRoutine));return}const meal=event.target.closest("[data-remove-meal]");if(meal){removeMeal(Number(meal.dataset.removeMeal));return}const range=event.target.closest("[data-range]");if(range){historyRange=range.dataset.range;document.querySelectorAll("[data-range]").forEach(function(b){b.classList.toggle("selected",b===range)});renderInsights();return}const cat=event.target.closest("[data-category]");if(cat){exerciseCategory=cat.dataset.category;renderCategories();renderExercises();return}const pass=event.target.closest("[data-trainer-pass]");if(pass){stepTrainer(1);return}const save=event.target.closest("[data-trainer-save]");if(save){saveTrainer(save.dataset.trainerSave);return}const prompt=event.target.closest("[data-prompt]");if(prompt&&prompt.closest(".chat-quick-prompts")){appendMessage(prompt.dataset.prompt,"user");$("chatForm").elements.message.value=prompt.dataset.prompt;$("chatForm").requestSubmit();return}});
 $("exerciseSearch").addEventListener("input",function(e){libraryQuery=e.target.value;renderExercises()});$("libraryDifficulty").addEventListener("change",function(e){libraryDifficulty=e.target.value;renderExercises()});
 $("goalForm").addEventListener("submit",updateMovementGoal);$("repForm").addEventListener("submit",logReps);$("nutritionForm").addEventListener("submit",calculateDiet);$("profileForm").addEventListener("submit",saveTrainingProfile);$("prForm").addEventListener("submit",addPR);$("healthForm").addEventListener("submit",saveHealth);$("symptomForm").addEventListener("submit",checkSymptoms);$("symptomForm").elements.pain.addEventListener("input",function(e){$("painScore").textContent=e.target.value});$("buddyForm").addEventListener("submit",findBuddies);$("chatForm").addEventListener("submit",sendChat);$("accountForm").addEventListener("submit",signIn);$("foodPhoto").addEventListener("change",function(e){previewFoodPhoto(e.target.files[0])});$("foodSearch").addEventListener("input",function(e){renderFoodResults(e.target.value)});
 ["rankScope","rankCountry","rankRegion","rankType"].forEach(function(id){$(id).addEventListener("change",function(){if(id==="rankCountry")updateRegionOptions();renderLeaderboardFromPrefs()})});
 $("trainerSpecialty").addEventListener("change",function(){trainerIndex=0;renderTrainers()});$("trainerMode").addEventListener("change",function(){trainerIndex=0;renderTrainers()});$("drawerBackdrop").addEventListener("click",closeCoach);
 ["nutritionDialog","profileDialog","exerciseDialog"].forEach(function(id){$(id).addEventListener("click",function(e){if(e.target===$(id))$(id).close()})});$("sessionDialog").addEventListener("close",function(){if(sessionTimer){clearInterval(sessionTimer);sessionTimer=null}if(restInterval){clearInterval(restInterval);restInterval=null}session=null});document.addEventListener("keydown",function(e){if(e.key==="Escape")closeCoach()});
}
function setUserMode(mode){$("accountForm").dataset.mode=mode}
async function signIn(event){event.preventDefault();await performAuth("signin")}
async function signup(){await performAuth("signup")}
async function performAuth(mode){if(!supabaseClient){$("accountMessage").textContent="Cloud accounts need Supabase setup and an HTTP preview. Local features still work.";return}const f=$("accountForm"),email=f.elements.email.value.trim(),password=f.elements.password.value;if(!email||password.length<8){$("accountMessage").textContent="Enter a valid email and a password of at least 8 characters.";return}const buttons=f.querySelectorAll("button");buttons.forEach(function(b){b.disabled=true});try{let response;if(mode==="signup")response=await supabaseClient.auth.signUp({email:email,password:password});else response=await supabaseClient.auth.signInWithPassword({email:email,password:password});if(response.error)throw response.error;if(mode==="signup"&&!response.data.session){$("accountMessage").textContent="Check your email to confirm your account, then sign in.";return}currentUser=response.data.user;await loadCloudState();$("accountDialog").close();notify("Signed in. Your cloud save is active.")}catch(e){$("accountMessage").textContent=e.message||"Authentication failed."}finally{buttons.forEach(function(b){b.disabled=false})}}
async function signOut(){if(!supabaseClient||!currentUser){$("accountDialog").showModal();$("accountMessage").textContent="You are using local demo mode.";return}const result=await supabaseClient.auth.signOut();if(result.error){notify(result.error.message);return}currentUser=null;cloudLoaded=false;setConnection("Local demo · saved here");$("accountDialog").close();notify("Signed out. This device keeps its saved demo data.")}
async function initSupabase(){const config=window.FORGE_CONFIG;if(!config||!config.url||!config.anonKey||config.url.includes("YOUR_PROJECT")||location.protocol==="file:"){setConnection("Local demo · saved here");$("accountButton")?.classList.add("local-only");return}const script=document.createElement("script");script.src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2";script.onload=async function(){try{supabaseClient=window.supabase.createClient(config.url,config.anonKey);const result=await supabaseClient.auth.getSession();currentUser=result.data.session?.user||null;supabaseClient.auth.onAuthStateChange(function(event,session){currentUser=session?.user||null;if(event!=="INITIAL_SESSION")setTimeout(function(){if(currentUser)loadCloudState();else{cloudLoaded=false;setConnection("Local demo · saved here")}},0)});if(currentUser)await loadCloudState();else setConnection("Ready · sign in to sync")}catch(e){setConnection("Cloud setup needs attention");console.error(e)}};script.onerror=function(){setConnection("Local demo · AI service unavailable")};document.head.appendChild(script)}
async function loadCloudState(){if(!supabaseClient||!currentUser)return;setConnection("Loading secure cloud save…");const result=await supabaseClient.from("fitness_state").select("state").eq("user_id",currentUser.id).maybeSingle();if(result.error){setConnection("Signed in · cloud schema not ready");return}if(result.data&&result.data.state){state=Object.assign(defaultState(),result.data.state);state.profile=Object.assign(defaultState().profile,state.profile||{});state.movement=Object.assign(defaultState().movement,state.movement||{});cloudLoaded=true;localStorage.setItem(STORE_KEY,JSON.stringify(state));renderAll()}else{cloudLoaded=true;await saveCloudState()}setConnection("Cloud sync on · "+currentUser.email)}
function queueCloudSave(){if(!supabaseClient||!currentUser||!cloudLoaded)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(saveCloudState,700)}
async function saveCloudState(){if(!supabaseClient||!currentUser||!cloudLoaded)return;const result=await supabaseClient.from("fitness_state").upsert({user_id:currentUser.id,state:state,updated_at:new Date().toISOString()},{onConflict:"user_id"});if(result.error){setConnection("Cloud save failed · local copy kept");console.error(result.error.message)}else setConnection("Cloud sync on · saved")}
function renderSavedPhotoResult(){}
